function drawPoint(raw){guides=[];if(tool==='calibrate')return raw;const q=snap(raw,p.grid),l=L(),isWall=tool==='wall'||tool==='room';if(isWall){const near=l.walls.flatMap(w=>[w.a,w.b]).find(a=>dist(a,raw)<Math.min(.3,12/zoom));if(near){if(display.magnet)guides=[{axis:'x',value:near.x},{axis:'y',value:near.y}];return near}const hit=nearestWall(raw,l);if(hit&&hit.d<Math.min(.2,9/zoom))return hit.q}const base=tool==='wall'&&start&&p.angleSnap?angleSnap(start,q,p.angleSnap):q;if(display.magnet){const hit=magnetPoint(l,p,raw,magnetThreshold(),{axes:!(tool==='wall'&&start&&p.angleSnap)});if(hit){guides=hit.guides;return {x:hit.guides.some(g=>g.axis==='x')?hit.point.x:base.x,y:hit.guides.some(g=>g.axis==='y')?hit.point.y:base.y}}}return base}
function snapVertex(raw,v){guides=[];const base=snap(raw,p.grid);if(!display.magnet)return base;const hit=magnetPoint(L(),p,raw,magnetThreshold(),{excludePoint:v.original,excludeSelection:v.selection});if(!hit)return base;guides=hit.guides;return{x:hit.guides.some(g=>g.axis==='x')?hit.point.x:base.x,y:hit.guides.some(g=>g.axis==='y')?hit.point.y:base.y}}

function paintPreview(){const g=$('#draftPreview');if(!g)return;if(vertexDrag){g.innerHTML=vertexPreview(vertexDrag)+guideMarkup()+loupeMarkup(vertexDrag.point);return}if(objectDrag){const o={...objectDrag.object,...objectDrag.point};g.innerHTML='<polygon data-object-preview="1" points="'+footprint(o).map(v=>X(v.x)+','+Y(v.y)).join(' ')+'" fill="#16897b25" stroke="#16897b" stroke-width="2" stroke-dasharray="6 4"/>'+guideMarkup();return}const q=previewPoint,a=start||polyDraft.at(-1);if(!q||!a){g.innerHTML=q?guideMarkup()+loupeMarkup(q):'';return}const point=v=>X(v.x)+','+Y(v.y),rect=['room','landRect'].includes(tool),pts=rect?rectanglePoints(a,q):[a,q],angle=lineAngle(a,q),previous=tool==='wall'?lastWallStart:polyDraft.length>1?polyDraft.at(-2):null,corner=previous?cornerAngle(previous,a,q):null,label=rect?Math.abs(q.x-a.x).toFixed(2)+' × '+Math.abs(q.y-a.y).toFixed(2)+' m · '+Math.abs((q.x-a.x)*(q.y-a.y)).toFixed(2)+' m²':dist(a,q).toFixed(2)+' m'+(display.angles?' · '+angle.toFixed(1)+'°'+(corner!==null?' · Ecke '+corner.toFixed(1)+'°':''):'');g.innerHTML=(rect?'<polygon':'<polyline')+' data-live-preview="1" points="'+pts.map(point).join(' ')+'" fill="'+(rect?'#16897b20':'none')+'" stroke="#087d70" stroke-width="2.5" stroke-dasharray="8 5"/><circle cx="'+X(q.x)+'" cy="'+Y(q.y)+'" r="5" fill="#fff" stroke="#087d70" stroke-width="2"/><text x="'+X((a.x+q.x)/2)+'" y="'+(Y((a.y+q.y)/2)-10)+'" text-anchor="middle" font-size="13" font-weight="bold" stroke="#fff" stroke-width="4" paint-order="stroke" fill="#06564e">'+label+'</text>'+(!rect&&display.angles&&dist(a,q)>.001?angleGuide(a,q,angle):'')+guideMarkup()+loupeMarkup(q)}
function updateDraftBar(){const bar=$('#draftbar');if(!bar)return;const poly=['route','landscape','roofPatch','parcelPolygon'].includes(tool),active=mode!=='3d'&&!walk&&(poly||['wall','room','curve','measure','landRect','calibrate'].includes(tool));bar.classList.toggle('hidden',!active);if(!active)return;const min=tool==='route'?2:3;$('#draftFinish').disabled=poly&&polyDraft.length<min;$('#draftExact').hidden=!start||!['wall','room','landRect','measure'].includes(tool);$('#draftUndo').disabled=!start&&!polyDraft.length&&!curveStart.length;$('#draftHint').textContent=poly?polyDraft.length+' Punkte · '+(polyDraft.length>=min?'Fertig zum Speichern':'mind. '+min):start?'Endpunkt ziehen und loslassen':'Startpunkt setzen'}

function importBlueprint(){const input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg,image/webp,application/pdf';input.onchange=async()=>{const file=input.files[0];if(!file)return;try{if(file.size>12e6)throw Error('Datei zu gross (max. 12 MB)');const canvas=document.createElement('canvas');if(file.type==='application/pdf'||file.name.toLowerCase().endsWith('.pdf')){const {renderPDF}=await import('./pdf-import.js');await renderPDF(file,canvas)}else{if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Bitte PNG/JPG/WebP oder PDF wählen');const bm=await createImageBitmap(file),s=Math.min(1,1600/Math.max(bm.width,bm.height));canvas.width=Math.max(1,Math.round(bm.width*s));canvas.height=Math.max(1,Math.round(bm.height*s));canvas.getContext('2d').drawImage(bm,0,0,canvas.width,canvas.height);bm.close();}const width=prompt('Tatsächliche Breite des gesamten Bildes in Metern','10');if(width===null)return;const w=num(width,.1,200);transact(()=>L().blueprint={data:canvas.toDataURL('image/jpeg',.72),x:0,y:0,width:w,height:w*canvas.height/canvas.width});status('Vorlage geladen. Wände darüber nachzeichnen.')}catch(e){status(e.message)}};input.click()}

async function importModel(){const input=document.createElement('input');input.type='file';input.accept='.glb,model/gltf-binary';input.onchange=async()=>{try{const file=input.files[0];if(!file||file.size>2e6)throw Error('GLB bis 2 MB wählen');const {inspectGLB}=await import('./models.js');const bytes=await file.arrayBuffer();const info=await inspectGLB(bytes);const name=prompt('Objektname',file.name.replace(/\.glb$/i,''));if(name===null)return;const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(new Blob([bytes],{type:'model/gltf-binary'}))});transact(()=>L().objects.push({kind:'custom',id:uid(),name:name.slice(0,100),x:1,y:1,rotation:0,elevation:0,width:info.width,depth:info.depth,height:info.height,color:'#b0b0b0',modelData:data}));status('Modell eingefügt; Position und Masse im Eigenschaftenmenü bearbeiten.')}catch(e){status(e.message)}};input.click()}

function restoreBackup(){const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{const file=input.files[0];if(!file||file.size>100e6)throw Error('Sicherung fehlt oder ist zu gross');const data=JSON.parse(await file.text());if(data.format!=='homecraft-backup-v1'||!Array.isArray(data.projects)||data.projects.length>200)throw Error('Ungültige Sicherung');const next=data.projects.map(validate).map(q=>({...q,id:uid()}));if(!confirm(next.length+' Projekte als neue Kopien hinzufügen?'))return;projects.push(...next);save();home()}catch(e){status(e.message)}};input.click()}

function fitPlan(){const r=$('#svg').getBoundingClientRect(),l=L(),pts=l.walls.flatMap(w=>[w.a,w.b]).concat(l.objects.flatMap(o=>[{x:o.x-o.width/2,y:o.y-o.depth/2},{x:o.x+o.width/2,y:o.y+o.depth/2}]),p.parcel?.points||[],(p.landscape||[]).flatMap(a=>a.points));if(!pts.length)return;const a=Math.min(...pts.map(p=>p.x)),b=Math.max(...pts.map(p=>p.x)),c=Math.min(...pts.map(p=>p.y)),d=Math.max(...pts.map(p=>p.y));zoom=Math.max(8,Math.min(220,(r.width-50)/Math.max(1,b-a),(r.height-50)/Math.max(1,d-c)));origin={x:r.width/2-(a+b)/2*zoom,y:r.height/2-(c+d)/2*zoom};draw()}

function materialSelect(label,id,value,optional=false){return '<label>'+esc(label)+'<select id="'+id+'">'+(optional?'<option value="">Einfarbig</option>':'')+materials.map(m=>'<option value="'+m.id+'" '+(value===m.id?'selected':'')+'>'+esc(m.name)+'</option>').join('')+'</select></label>'}
function materialGallery(){const d=dialog('Materialbibliothek · '+materials.length,'<input type="search" id="matSearch" aria-label="Material suchen" placeholder="Material suchen"><div class="catalog" id="matItems"></div>');const draw=()=>{const q=d.querySelector('#matSearch').value.toLowerCase(),items=d.querySelector('#matItems');items.replaceChildren();for(const m of materials.filter(m=>m.name.toLowerCase().includes(q))){const e=document.createElement('div');e.className='project';const canvas=surfaceTexture(m.id);canvas.style.cssText='width:100%;aspect-ratio:1;border-radius:6px';const name=document.createElement('small');name.textContent=m.name;e.append(canvas,name);items.append(e)}};d.querySelector('#matSearch').oninput=draw;draw()}
function layoutDialog(kind){const kitchen=kind==='kitchen',d=dialog(kitchen?'Küchenplaner':'Badezimmerplaner','<div class="row">'+(kitchen?'<label>Form<select id="shape"><option value="straight">Gerade</option><option value="L">L-Form</option><option value="U">U-Form</option><option value="island">Insel</option></select></label>':'<label>Sanitär<select id="bathType"><option value="shower">Dusche</option><option value="bath">Badewanne</option></select></label>')+field('Breite / Länge m','length',3)+field('Tiefe / Seite m','side',2.5)+field('X m','lx',1)+field('Y m','ly',1)+field('Drehung °','lr',0)+(kitchen?'<label><input type="checkbox" id="upper" checked> Oberschränke</label>':'')+'</div><p>Die zusammengehörigen Module werden eingefügt und bleiben einzeln bearbeitbar. Platz und Durchgänge bitte prüfen.</p><button class="primary" id="layoutApply">Einfügen</button>');const n=id=>Number(d.querySelector('#'+id).value);d.querySelector('#layoutApply').onclick=()=>{if(transact(()=>{const origin={x:num(n('lx'),-1000,1000),y:num(n('ly'),-1000,1000)},rotation=num(n('lr'),-360,360);const items=kitchen?kitchenLayout(origin,{shape:d.querySelector('#shape').value,length:num(n('length'),1.2,8),side:num(n('side'),1.2,6),rotation,upper:d.querySelector('#upper').checked}):bathroomLayout(origin,{width:num(n('length'),2.2,10),depth:num(n('side'),2,10),rotation,bath:d.querySelector('#bathType').value==='bath'});L().objects.push(...items)}))d.remove()}}
function budgetDialog(){const d=dialog('Kostenplaner','<div class="row">'+field('Boden CHF/m²','bf',40)+field('Verlegung CHF/m²','bl',25)+field('Verschnitt %','bw',10)+field('Wand CHF/m²','bp',15)+field('Tür CHF/Stk','bd',400)+field('Fenster CHF/Stk','bwin',600)+'</div><div id="budgetResult"></div><p>Eigene Richtpreise, keine Offerte oder Marktpreisabfrage.</p><button id="budgetCSV">CSV exportieren</button>');const rates=()=>{const n=id=>Math.max(0,Number(d.querySelector('#'+id).value)||0);return{floor:n('bf'),labor:n('bl'),waste:n('bw'),paint:n('bp'),door:n('bd'),window:n('bwin')}};const update=()=>{const rows=roomCosts(p,rates());d.querySelector('#budgetResult').innerHTML=rows.map(r=>'<p>'+esc(r.name)+': CHF '+r.cost.toFixed(2)+'</p>').join('')+'<strong>Total CHF '+rows.reduce((s,r)=>s+r.cost,0).toFixed(2)+'</strong>'};d.querySelectorAll('input').forEach(i=>i.oninput=update);d.querySelector('#budgetCSV').onclick=()=>download('Kosten.csv',new Blob(['Geschoss;Kosten CHF\n'+roomCosts(p,rates()).map(r=>'"'+("'"+r.name).replaceAll('"','""')+'";'+r.cost.toFixed(2)).join('\n')],{type:'text/csv'}));update()}

