function sunDialog(){const a=p.sun||{date:new Date().toISOString().slice(0,10),hour:12,lat:47,lon:8,utc:1,north:0},d=dialog('Sonnenstand','<div class="row">'+field('Datum','sunDate',a.date,'date')+field('Stunde lokal','sunHour',a.hour)+field('Breitengrad','sunLat',a.lat)+field('Längengrad','sunLon',a.lon)+field('UTC-Abweichung','sunUTC',a.utc)+field('Norddrehung °','sunNorth',a.north)+'</div><p>Geometrische Näherung, kein zertifizierter Verschattungsnachweis. UTC-Abweichung inkl. Sommerzeit selbst eingeben.</p><button id="sunApply">Anwenden</button>');d.querySelector('#sunApply').onclick=()=>{const v=id=>d.querySelector('#'+id).value;try{const sun={date:v('sunDate'),hour:num(v('sunHour'),0,24),lat:num(v('sunLat'),-89.9,89.9),lon:num(v('sunLon'),-180,180),utc:num(v('sunUTC'),-14,14),north:num(v('sunNorth'),-360,360)};solarPosition(sun.date,sun.hour,sun.lat,sun.lon,sun.utc,sun.north);mode='3d';walk=false;night=false;if(transact(()=>p.sun=sun))d.remove()}catch(e){status(e.message)}}}

