function cameraDialog(){ensure3D();const d=dialog('Kamerapositionen','<button id="saveCamera">Aktuelle Ansicht speichern</button><div id="cameraList"></div>');const draw=()=>{d.querySelector('#cameraList').innerHTML=(p.cameras||[]).map(c=>'<div class="row"><button data-camera="'+esc(c.id)+'">'+esc(c.name)+'</button><button data-remove-camera="'+esc(c.id)+'">Löschen</button></div>').join('')||'<p>Noch keine Kameraposition gespeichert.</p>';d.querySelectorAll('[data-camera]').forEach(b=>b.onclick=()=>{const c=p.cameras.find(c=>c.id===b.dataset.camera);if(!p.levels.some(l=>l.id===c.level)){status('Geschoss fehlt.');return}lid=c.level;walk=c.walk;fly=false;mode=walk?'walk':'3d';presentation={};render(true);view.restoreCamera(c);d.remove()});d.querySelectorAll('[data-remove-camera]').forEach(b=>b.onclick=()=>{transact(()=>p.cameras=p.cameras.filter(c=>c.id!==b.dataset.removeCamera));draw()})};d.querySelector('#saveCamera').onclick=()=>{const name=prompt('Kameraname','Ansicht '+((p.cameras||[]).length+1));if(name)transact(()=>storeCamera(p,name,view.cameraState()));draw()};draw()}

