async function setupBiometricButtons(d){if(!Capacitor.isNativePlatform())return;try{const s=await BiometricVault.status();if(!s.available)return;const enable=d.querySelector('#bioEnable'),disable=d.querySelector('#bioDisable');enable.hidden=false;disable.hidden=!s.enabled;enable.onclick=()=>{const e=dialog('Biometrie einrichten','<p>Android 11+ mit registrierter starker Biometrie. Die Passphrase bleibt als Alternative erforderlich.</p><label>Passphrase<input type="password" id="bioPass" autocomplete="current-password"></label><button id="bioConfirm">Einrichten</button><p id="bioError" role="alert"></p>');e.querySelector('#bioConfirm').onclick=async()=>{const button=e.querySelector('#bioConfirm');button.disabled=true;try{const password=e.querySelector('#bioPass').value,stored=await readProjects(database),key=await deriveVaultKey(password,stored.salt);await decryptProjects(stored,key);await BiometricVault.enable({password});e.remove();disable.hidden=false;alert('Biometrie eingerichtet.')}catch(err){e.querySelector('#bioError').textContent='Einrichtung fehlgeschlagen. Passphrase und Biometrie prüfen.';button.disabled=false}}};disable.onclick=async()=>{try{await BiometricVault.clear();disable.hidden=true}catch(e){alert(e.message)}}}catch{}}

