function myModelsDialog(){const models=reusableModels(projects),d=dialog('Meine 3D-Modelle',models.length?'<p>Bereits importierte Modelle aus deinen lokalen Projekten erneut platzieren.</p><div class="catalog">'+models.map((o,i)=>'<button data-my-model="'+i+'">'+esc(o.name)+'<br><small>'+o.width.toFixed(2)+' × '+o.depth.toFixed(2)+' m</small></button>').join('')+'</div>':'<p>Noch keine eigenen GLB-Modelle vorhanden. Importiere zuerst ein Modell.</p>');d.querySelectorAll('[data-my-model]').forEach(b=>b.onclick=()=>{customPick=models[Number(b.dataset.myModel)];tool='furniture';mode='2d';walk=false;d.remove();render();status('Position für das eigene Modell antippen.')})}
function compareDialog(){const others=projects.filter(q=>q.id!==p.id),d=dialog('Entwurfsvergleich','<p>Violette gestrichelte Wände zeigen den Vergleichsentwurf im aktuellen Koordinatensystem. Gleicher Ursprung empfohlen.</p><label>Projekt<select id="cmpProject"><option value="">Auswählen</option>'+others.map(q=>'<option value="'+esc(q.id)+'">'+esc(q.name)+'</option>').join('')+'</select></label><label>Geschoss<select id="cmpLevel"></select></label><div id="cmpResult"></div><button id="cmpApply">Überlagern</button><button id="cmpClear">Vergleich ausblenden</button>');const select=d.querySelector('#cmpProject'),levels=d.querySelector('#cmpLevel'),pick=()=>others.find(q=>q.id===select.value)?.levels.find(l=>l.id===levels.value);select.onchange=()=>{levels.innerHTML=(others.find(q=>q.id===select.value)?.levels||[]).map(l=>'<option value="'+esc(l.id)+'">'+esc(l.name)+'</option>').join('');update()};const update=()=>{const l=pick();if(!l){d.querySelector('#cmpResult').textContent='Kein Vergleichsgeschoss ausgewählt.';return}const a=compareLevels(L(),l);d.querySelector('#cmpResult').textContent='Vergleich minus aktuell: '+a.delta.floor.toFixed(2)+' m², '+a.delta.walls.toFixed(2)+' m Wandlänge, '+a.delta.rooms+' Räume, '+a.delta.objects+' Objekte.'};levels.onchange=update;d.querySelector('#cmpApply').onclick=()=>{const l=pick();if(!l)return;comparison=copy(l);mode='2d';walk=false;d.remove();render();status('Vergleich eingeblendet. Menü > Entwürfe vergleichen zum Ausblenden.')};d.querySelector('#cmpClear').onclick=()=>{comparison=null;d.remove();render()};update()}

function parcelDialog(){const a=p.parcel||{},d=dialog('Bauland nach Mass','<p>Rechteckiges Grundstück mit exakten Abmessungen oder freie Grenze. Eine vorhandene Grenze wird ersetzt, Haus und Aussenflächen bleiben erhalten.</p><div class="row">'+field('Breite m','parcelW',a.width??20)+field('Länge m','parcelD',a.depth??30)+field('X m','parcelX',a.x??0)+field('Y m','parcelY',a.y??0)+field('Drehung °','parcelR',a.rotation??0)+'</div><p id="parcelArea"></p><button id="parcelApply" class="primary">Grundstück erstellen</button><button id="parcelFree">Freie Grundstücksgrenze zeichnen</button>');const val=id=>d.querySelector('#'+id).value,update=()=>{d.querySelector('#parcelArea').textContent='Fläche: '+(Number(val('parcelW'))*Number(val('parcelD'))).toFixed(2)+' m²'};d.querySelectorAll('input').forEach(i=>i.oninput=update);update();d.querySelector('#parcelApply').onclick=()=>{if(transact(()=>setParcel(p,{width:num(val('parcelW'),.5,500),depth:num(val('parcelD'),.5,500),x:num(val('parcelX'),-1000,1000),y:num(val('parcelY'),-1000,1000),rotation:num(val('parcelR'),-360,360)}))){d.remove();start=null;polyDraft=[];previewPoint=null;tool='select';mode='2d';walk=false;render();fitPlan();status('Bauland erstellt.')}};d.querySelector('#parcelFree').onclick=()=>{start=null;polyDraft=[];previewPoint=null;tool='parcelPolygon';mode='2d';walk=false;d.remove();render();status('Grenzpunkte setzen, dann ✓ Fertig oder ersten Punkt antippen.')}}
function siteStatsDialog(){const q=parcelCoverage(p);dialog('Grundstücksübersicht',q?'<p>Grundstücksfläche: <strong>'+q.area.toFixed(2)+' m²</strong></p><p>Grenzlänge: '+q.perimeter.toFixed(2)+' m</p><p>Netto-Raumfläche des erdnahen Geschosses: '+q.netFloor.toFixed(2)+' m²</p><p>Verhältnis Netto-Raumfläche zu Grundstück: '+q.netRatio.toFixed(1)+' %</p><p>Keine rechtliche Ausnützungs- oder Überbauungsziffer.</p>':'<p>Erstelle zuerst ein Bauland nach Mass.</p>')}

function exactDrawingDialog(){if(!start)return;const a={...start},k=tool,isRect=['room','landRect'].includes(k),d=dialog(isRect?'Exakte Fläche':'Exakte Linie','<div class="row">'+(isRect?field('Breite X m','exactX',4)+field('Tiefe Y m','exactY',3):field('Länge m','exactLength',3)+field('Winkel ° (0 = rechts)','exactAngle',0))+'</div><p>Negative X/Y-Masse zeichnen in die Gegenrichtung. 90° zeigt im Plan nach unten.</p><button id="exactApply" class="primary">Erstellen</button>');const v=id=>d.querySelector('#'+id).value;d.querySelector('#exactApply').onclick=()=>{try{const q=isRect?{x:a.x+num(v('exactX'),-500,500),y:a.y+num(v('exactY'),-500,500)}:endpointAt(a,num(v('exactLength'),.05,500),num(v('exactAngle'),-360,360));if(transact(()=>{if(k==='wall')insertWall(L(),a,q);else if(k==='room')rectangle(L(),a,q);else if(k==='landRect')addLandscape(p,drawLand,rectanglePoints(a,q));else (L().notes??=[]).push({type:'measure',a,b:q})})){lastWallStart=k==='wall'?a:null;start=k==='wall'?q:null;previewPoint=null;if(k==='landRect')tool='select';d.remove();render();status('Massgenau erstellt.')}}catch(e){status(e.message)}}}
function exactLandscapeDialog(){const d=dialog('Aussenfläche nach Mass','<label>Oberfläche<select id="exactLandType">'+landscapeTypes.map(([id,name])=>'<option value="'+id+'">'+esc(name)+'</option>').join('')+'</select></label><div class="row">'+field('Breite m','elW',5)+field('Länge m','elD',4)+field('X m','elX',0)+field('Y m','elY',0)+field('Höhe m','elZ',0)+'</div><button id="elApply" class="primary">Fläche erstellen</button>');const v=id=>d.querySelector('#'+id).value;d.querySelector('#elApply').onclick=()=>{if(transact(()=>{const x=num(v('elX'),-1000,1000),y=num(v('elY'),-1000,1000),w=num(v('elW'),.1,500),h=num(v('elD'),.1,500);addLandscape(p,v('exactLandType'),rectanglePoints({x,y},{x:x+w,y:y+h}),num(v('elZ'),-20,20))})){d.remove();fitPlan();status('Aussenfläche massgenau erstellt.')}}}

function angleGuide(a,q,angle){const r=23,rad=angle*Math.PI/180,x=X(a.x),y=Y(a.y),endX=x+r*Math.cos(rad),endY=y+r*Math.sin(rad);return '<path d="M'+x+' '+y+'h'+(r+12)+' M'+(x+r)+' '+y+' A'+r+' '+r+' 0 '+(angle>180?1:0)+' 1 '+endX+' '+endY+'" fill="none" stroke="#16897b" stroke-width="1.4" stroke-dasharray="3 3"/>'}
const displayLabels={grid:'Raster',wallMeasures:'Wandmasse',angles:'Zeichenwinkel und Eckwinkel',roomNames:'Raumnamen',roomAreas:'Raumflächen',objectNames:'Möbelnamen',objectMeasures:'Möbelmasse',openingMeasures:'Tür- und Fenstermasse',notes:'Textnotizen',dimensions:'Eigene Masslinien',landLabels:'Aussenflächen-Beschriftung',parcelMeasures:'Grundstücksmasse',doorArcs:'Türöffnungsbögen',ghost:'Unteres Geschoss als Hilfsebene',objects:'Möbel anzeigen',landscape:'Aussenflächen anzeigen',technical:'Technische Leitungen anzeigen',roofPatches:'Dachflächen anzeigen',blueprint:'Importierte Planvorlage',magnet:'Magnetische Hilfslinien',magnifier:'Zeichenlupe',handles:'Bearbeitbare Eckpunkte'};
function displayDialog(){const d=dialog('Anzeigeeinstellungen (2D)','<p>Die Einstellungen gelten für alle Projekte auf diesem Gerät. Die Geometrie wird nicht verändert.</p><div class="displayPresets"><button data-preset="clean">'+uiIcon('clean')+'Aufgeräumt</button><button data-preset="detail">'+uiIcon('detail')+'Alle Details</button><button data-preset="default">'+uiIcon('default')+'Standard</button></div>'+displayGroups.map(([title,ids])=>'<section class="displaySection"><h3>'+title+'</h3><div class="displayList">'+ids.map(id=>'<label><span>'+esc(displayLabels[id])+'</span><input type="checkbox" role="switch" data-display="'+id+'" '+(display[id]?'checked':'')+'></label>').join('')+'</div></section>').join('')+'');const update=()=>{try{localStorage.setItem('homecraft.display',JSON.stringify(display))}catch{}draw();d.querySelectorAll('[data-display]').forEach(b=>b.checked=display[b.dataset.display])};d.querySelectorAll('[data-display]').forEach(b=>b.onchange=()=>{display[b.dataset.display]=b.checked;update()});d.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{const k=b.dataset.preset;display=displaySettings(k==='default'?{}:Object.fromEntries(Object.keys(displayDefaults).map(id=>[id,k==='detail'||['angles','objects','landscape','blueprint','magnet','handles','magnifier'].includes(id)])));update()})}

function selectionFrom(d){return d.opening?{type:'opening',id:d.opening,parent:d.parent}:d.object?{type:'object',id:d.object}:d.wall?{type:'wall',id:d.wall}:d.room?{type:'room',id:d.room}:d.route?{type:'route',id:d.route}:d.landscape?{type:'landscape',id:d.landscape}:d.roofpatch?{type:'roofpatch',id:d.roofpatch}:d.parcel?{type:'parcel',id:'parcel'}:null}
function addContextButton(){const el=$('#inspector');if(!selected||!el||el.classList.contains('hidden')||el.querySelector('#moreObject'))return;const b=document.createElement('button');b.id='moreObject';b.textContent='Weitere Aktionen ⋯';b.onclick=()=>openContext(selected);el.append(b)}
function entityTitle(s,x){return s.type==='wall'?'Wand':s.type==='opening'?(x.type==='door'?'Tür':'Fenster'):s.type==='object'||s.type==='room'?x.name:s.type==='parcel'?'Bauland':s.type==='landscape'?(landscapeTypes.find(a=>a[0]===x.kind)?.[1]||'Aussenfläche'):s.type==='route'?(systems.find(a=>a.id===x.system)?.name||'Leitung'):'Dachfläche'}
function openContext(s){if(!s||!p||document.querySelector('.contextModal'))return;const l=L(),x=selectedEntity(p,l,s);if(!x)return;selected=s;tool='select';start=null;lastWallStart=null;curveStart=[];polyDraft=[];previewPoint=null;draw();inspect();addContextButton();const actions=[['edit','Bearbeiten'],['measure','Masse hinzufügen'],['center','In Ansicht zentrieren'],['info','Details anzeigen']];if(['wall','parcel','landscape','roofpatch','route'].includes(s.type))actions.push(['vertices','Eckpunkte bearbeiten']);if(['wall','object','opening','landscape','roofpatch','room'].includes(s.type))actions.push(['color',s.type==='room'?'Bodenmaterial':'Farbe ändern']);if(s.type==='object')actions.push(['duplicate','Duplizieren'],['rotate','Um 90° drehen'],['lock',x.locked?'Entsperren':'Position sperren'],['rename','Umbenennen']);if(s.type==='wall')actions.push(['wallLength','Länge / Winkel ändern'],['wallReverse','Wandrichtung umkehren']);if(s.type==='opening'&&x.type==='door')actions.push(['door',x.open?'Tür schliessen':'Tür öffnen']);if(s.type==='room')actions.push(['furnish','Einrichtung vorschlagen'],['rename','Raum umbenennen']);if(s.type==='landscape')actions.push(['surface','Oberfläche ändern'],['duplicate','Fläche duplizieren']);if(s.type==='parcel')actions.push(['parcel','Grundstücksmass ändern']);if(s.type!=='room')actions.push(['delete','Löschen']);const d=dialog(entityTitle(s,x),'<div class="contextSummary"><span class="contextGlyph">'+uiIcon(({object:'furniture',opening:'door',roofpatch:'roofPatch'})[s.type]||s.type)+'</span><div><strong>'+esc(entityTitle(s,x))+'</strong><small>Ausgewähltes Element</small></div></div><div class="contextActions">'+actions.map(([id,n])=>'<button data-context="'+id+'" class="'+(id==='delete'?'danger':id==='edit'?'contextPrimary':'')+'">'+uiIcon(id)+'<span>'+esc(n)+'</span></button>').join('')+'</div>');d.classList.add('contextModal');d.querySelectorAll('[data-context]').forEach(b=>b.onclick=()=>{const k=b.dataset.context;d.remove();try{if(k==='vertices'){display.handles=true;persistDisplay();mode='2d';walk=false;tool='select';render();status('Grüne Eckpunkte ziehen und loslassen.');return}if(k==='edit'){inspect();addContextButton();$('#inspector').scrollIntoView({block:'nearest'});return}if(k==='measure'){let added=0;if(transact(()=>added=dimensionNotes(l,s,p))){display.dimensions=true;persistDisplay();draw();status(added?added+' Masslinie(n) hinzugefügt. Aktualisieren sich automatisch.':'Masse bereits vorhanden.')}return}if(k==='center'){const segments=elementDimensions(l,s,p),pts=segments.flat();if(pts.length){const r=$('#svg').getBoundingClientRect(),xs=pts.map(q=>q.x),ys=pts.map(q=>q.y);origin.x=r.width/2-(Math.min(...xs)+Math.max(...xs))/2*zoom;origin.y=r.height/2-(Math.min(...ys)+Math.max(...ys))/2*zoom;draw()}return}if(k==='info'){const pairs=elementDimensions(l,s,p);dialog(entityTitle(s,x)+' · Details','<p>'+pairs.length+' Kante(n)</p>'+pairs.map(([a,b],i)=>'<p>Kante '+(i+1)+': '+dist(a,b).toFixed(3)+' m · '+lineAngle(a,b).toFixed(1)+'°</p>').join('')+(s.type==='room'?'<p>Nettofläche: '+x.area.toFixed(2)+' m²</p>':s.type==='object'?'<p>Höhe: '+x.height.toFixed(2)+' m</p>':''));return}if(k==='color'){contextColor(s,x,l);return}if(k==='duplicate'){transact(()=>{const y=copy(x);y.id=uid();if(s.type==='object'){y.x+=.3;y.y+=.3;y.locked=false;delete y.groupId;l.objects.push(y)}else{y.points=y.points.map(q=>({...q,x:q.x+.3,y:q.y+.3}));p.landscape.push(y)}selected={type:s.type,id:y.id}});return}if(k==='rotate'){transact(()=>{if(x.locked)throw Error('Objekt ist gesperrt');x.rotation=(x.rotation+90)%360});return}if(k==='lock'){transact(()=>x.locked=!x.locked);return}if(k==='rename'){const name=prompt('Name',x.name);if(name!==null&&name.trim())transact(()=>{if(s.type==='room')(l.roomSettings??={})[x.id]={...l.roomSettings?.[x.id],name:name.trim().slice(0,100)};else x.name=name.trim().slice(0,100)});return}if(k==='wallLength'){contextWallLength(l,x);return}if(k==='wallReverse'){transact(()=>{const len=dist(x.a,x.b),a=x.a;x.a=x.b;x.b=a;for(const o of x.openings){o.t=len-o.t;if(o.type==='door')o.hinge=o.hinge==='right'?'left':'right'}const color=x.color,finish=x.finishInside;x.color=x.outer||x.color;x.outer=color;x.finishInside=x.finishOutside||'';x.finishOutside=finish||''});return}if(k==='door'){transact(()=>x.open=!x.open);return}if(k==='furnish'){furnishDialog(x);return}if(k==='surface'){const e=dialog('Oberfläche ändern','<label>Material<select id="surfaceKind">'+landscapeTypes.map(([id,n])=>'<option value="'+id+'" '+(x.kind===id?'selected':'')+'>'+esc(n)+'</option>').join('')+'</select></label><button id="surfaceApply">Übernehmen</button>');e.querySelector('#surfaceApply').onclick=()=>{if(transact(()=>{x.kind=e.querySelector('#surfaceKind').value;delete x.color}))e.remove()};return}if(k==='parcel'){parcelDialog();return}if(k==='delete'&&confirm(entityTitle(s,x)+' löschen?')){const remove=s.type==='parcel'?'#parcelDelete':'#remove';if(s.type==='parcel')transact(()=>{delete p.parcel;selected=null});else $(remove)?.click()}}catch(e){status(e.message)}})}
function persistDisplay(){try{localStorage.setItem('homecraft.display',JSON.stringify(display))}catch{}}
function contextColor(s,x,l){const room=s.type==='room',wall=s.type==='wall',e=dialog(room?'Bodenmaterial':'Farbe ändern',room?materialSelect('Boden','ctxFloor',x.floor):field('Farbe','ctxColor',x.color||(s.type==='landscape'?(x.kind==='water'?'#70b3d0':materialColor(landscapeFinish(x.kind))):'#b0b0b0'),'color')+(wall?'<label>Wandseite<select id="ctxSide"><option value="inside">Innen</option><option value="outside">Aussen</option><option value="both">Beide</option></select></label>':'') );const b=document.createElement('button');b.className='primary';b.textContent='Übernehmen';e.querySelector('.dialog').append(b);b.onclick=()=>{if(transact(()=>{if(room)(l.roomSettings??={})[x.id]={...l.roomSettings?.[x.id],name:x.name,floor:e.querySelector('#ctxFloor').value};else if(wall){const v=e.querySelector('#ctxColor').value,side=e.querySelector('#ctxSide').value;if(side!=='outside'){x.color=v;x.finishInside=''}if(side!=='inside'){x.outer=v;x.finishOutside=''}}else x.color=e.querySelector('#ctxColor').value}))e.remove()}}
function contextWallLength(l,w){const e=dialog('Wandlänge und Winkel',field('Länge m','ctxLen',dist(w.a,w.b))+field('Winkel °','ctxAngle',lineAngle(w.a,w.b))+'<button class="primary" id="ctxApply">Übernehmen</button>');e.querySelector('#ctxApply').onclick=()=>{if(transact(()=>editWall(l,w,{b:endpointAt(w.a,num(e.querySelector('#ctxLen').value,.05,500),num(e.querySelector('#ctxAngle').value,-360,360))})))e.remove()}}

function activateTool(id){const b=$('#tools [data-tool="'+id+'"]');if(!b)return;const planMode=mode==='2d'||mode==='split';if(!['select','pan','fit','plus','minus','cancel','abort','focus','fit2d'].includes(id)){const g=toolCategory(id,planMode);if(g){if(planMode)toolTab=g;else toolTab3D=g;renderToolVisibility()}}b.click()}
function renderToolVisibility(){const planMode=mode==='2d'||mode==='split',tab=planMode?toolTab:toolTab3D;$('#tools')?.querySelectorAll('[data-tool]').forEach(b=>b.hidden=b.dataset.toolSection!==tab);$('#toolTabs')?.querySelectorAll('[data-tool-group]').forEach(b=>{const active=b.dataset.toolGroup===tab;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});$('#tools')?.querySelectorAll('[data-tool]').forEach(b=>b.setAttribute('aria-pressed',String(tool===b.dataset.tool)));$('#quickStrip')?.querySelectorAll('[data-quick]').forEach(b=>b.classList.toggle('active',b.dataset.quick===tool))}
function applyFocusLayout(resize=true){const editor=app.querySelector('.editor');if(!editor)return;editor.classList.toggle('focusMode',focusMode);editor.classList.toggle('focusToolsVisible',focusMode&&focusTools);const b=$('#focusToggle'),t=$('#focusTools');b.innerHTML=toolIcon(focusMode?'unfocus':'focus');b.setAttribute('aria-label',focusMode?'Zeichenmodus verlassen':'Zeichenfläche maximieren');b.title=b.getAttribute('aria-label');t.hidden=!focusMode;t.setAttribute('aria-pressed',String(focusTools));if(resize){draw();view?.resize()}}
function setFocusMode(value){const svg=$('#svg'),r=svg?.getBoundingClientRect();focusMode=value;focusTools=false;applyFocusLayout(false);const n=svg?.getBoundingClientRect();if(r&&n&&r.width&&n.width&&r.height&&n.height){origin.x+=(n.width-r.width)/2;origin.y+=(n.height-r.height)/2}draw();view?.resize()}
function quickToolsDialog(){const all=[...new Set([...toolGroups(true),...toolGroups(false)].flatMap(g=>g.tools))].filter(id=>!['select','pan','fit','cancel','abort','focus'].includes(id));const d=dialog('Schnellzugriffe','<p>Wähle bis zu sechs persönliche Werkzeuge. Auswahl und Navigation sind immer verfügbar. Die Auswahl wird lokal gespeichert.</p><div class="quickConfig">'+all.map(id=>'<label>'+toolIcon(id)+'<span>'+esc(toolLabel(id))+'</span><input type="checkbox" data-pin="'+id+'" '+(quickTools.includes(id)?'checked':'')+'></label>').join('')+'</div><p id="pinCount" role="status"></p><div class="row"><button id="pinDefault">Standard</button><button id="pinSave" class="primary">Speichern</button></div>');const count=()=>{const n=d.querySelectorAll('[data-pin]:checked').length;d.querySelector('#pinCount').textContent=n+' / 6 Werkzeuge';d.querySelector('#pinSave').disabled=n>6;d.querySelectorAll('[data-pin]').forEach(b=>b.disabled=n>=6&&!b.checked)};d.querySelectorAll('[data-pin]').forEach(b=>b.onchange=count);d.querySelector('#pinDefault').onclick=()=>{const defaults=toolFavorites();d.querySelectorAll('[data-pin]').forEach(b=>b.checked=defaults.includes(b.dataset.pin));count()};d.querySelector('#pinSave').onclick=()=>{quickTools=toolFavorites([...d.querySelectorAll('[data-pin]:checked')].map(b=>b.dataset.pin));try{localStorage.setItem('homecraft.quickTools',JSON.stringify(quickTools))}catch{}d.remove();render()};count()}

function dimensionMarkup(n){const ax=X(n.a.x),ay=Y(n.a.y),bx=X(n.b.x),by=Y(n.b.y),dx=bx-ax,dy=by-ay,len=Math.hypot(dx,dy);if(len<.01)return '';const ux=dx/len,uy=dy/len,nx=-uy,ny=ux,off=n.ref?16:0,x1=ax+nx*off,y1=ay+ny*off,x2=bx+nx*off,y2=by+ny*off,tick=(x,y)=>'M'+(x-nx*5)+' '+(y-ny*5)+'L'+(x+nx*5)+' '+(y+ny*5);return '<g data-dimension="'+(n.ref?'linked':'manual')+'" pointer-events="none"><path d="M'+ax+' '+ay+'L'+x1+' '+y1+' M'+bx+' '+by+'L'+x2+' '+y2+' M'+x1+' '+y1+'L'+x2+' '+y2+' '+tick(x1,y1)+' '+tick(x2,y2)+'" stroke="#16897b" stroke-width="1.5" fill="none"/><text x="'+((x1+x2)/2+nx*8)+'" y="'+((y1+y2)/2+ny*8-3)+'" text-anchor="middle" paint-order="stroke" stroke="#fff" stroke-width="3" fill="#176b60" font-size="12">'+dist(n.a,n.b).toFixed(2)+' m</text></g>'}
function editablePoints(s){const x=selectedEntity(p,L(),s);return !x?[]:s.type==='wall'?[x.a,x.b]:['parcel','landscape','roofpatch','route'].includes(s.type)?x.points:[]}
function vertexHandles(){if(!selected||tool!=='select'||!display.handles)return '';return '<g id="vertexHandles">'+editablePoints(selected).map((q,i)=>'<circle data-vertex="'+i+'" cx="'+X(q.x)+'" cy="'+Y(q.y)+'" r="10" fill="#fff" stroke="#16897b" stroke-width="2.5"/><circle pointer-events="none" cx="'+X(q.x)+'" cy="'+Y(q.y)+'" r="3" fill="#16897b"/>').join('')+'</g>'}
function vertexPreview(v){const pts=editablePoints(v.selection).map((q,i)=>i===v.index?v.point:q),closed=['parcel','landscape','roofpatch'].includes(v.selection.type),path=closed?'polygon':'polyline';let h='<'+path+' points="'+pts.map(q=>X(q.x)+','+Y(q.y)).join(' ')+'" fill="'+(closed?'#16897b20':'none')+'" stroke="#16897b" stroke-dasharray="7 4" stroke-width="2.5"/>';if(v.selection.type==='wall'){for(const w of L().walls){if(w.id===v.selection.id)continue;const a=dist(w.a,v.original)<1e-5?v.point:w.a,b=dist(w.b,v.original)<1e-5?v.point:w.b;if(a!==w.a||b!==w.b)h+='<line x1="'+X(a.x)+'" y1="'+Y(a.y)+'" x2="'+X(b.x)+'" y2="'+Y(b.y)+'" stroke="#16897b" stroke-width="2" stroke-dasharray="7 4"/>'}}return h+'<circle cx="'+X(v.point.x)+'" cy="'+Y(v.point.y)+'" r="7" fill="#fff" stroke="#16897b" stroke-width="3"/>'}
function guideMarkup(){if(!display.magnet)return '';const svg=$('#svg');return guides.map(g=>g.axis==='x'?'<line data-magnet="x" x1="'+X(g.value)+'" x2="'+X(g.value)+'" y1="0" y2="'+svg.clientHeight+'" stroke="#2589b0" stroke-width="1.3" stroke-dasharray="6 4"/>':'<line data-magnet="y" x1="0" x2="'+svg.clientWidth+'" y1="'+Y(g.value)+'" y2="'+Y(g.value)+'" stroke="#2589b0" stroke-width="1.3" stroke-dasharray="6 4"/>').join('')}
function loupeMarkup(q){if(!display.magnifier||!loupeActive)return '';const svg=$('#svg'),r=48,w=svg.clientWidth,h=svg.clientHeight;if(w<120||h<120)return '';const px=X(q.x),py=Y(q.y),cx=Math.max(r+5,Math.min(w-r-5,px)),cy=py>r*2+22?py-r-28:Math.min(h-r-5,py+r+28);return '<g data-loupe="1"><defs><clipPath id="loupeClip"><circle cx="'+cx+'" cy="'+cy+'" r="'+r+'"/></clipPath></defs><circle cx="'+cx+'" cy="'+cy+'" r="'+r+'" fill="#f9faf8"/><g clip-path="url(#loupeClip)"><use href="#planContent" transform="translate('+cx+' '+cy+') scale(2.5) translate('+(-px)+' '+(-py)+')"/><path d="M'+(cx-r)+' '+cy+'H'+(cx+r)+' M'+cx+' '+(cy-r)+'V'+(cy+r)+'" stroke="#16897b" stroke-width="1.1" stroke-dasharray="3 3"/><circle cx="'+cx+'" cy="'+cy+'" r="4" fill="none" stroke="#16897b"/></g><circle cx="'+cx+'" cy="'+cy+'" r="'+r+'" fill="none" stroke="#176b60" stroke-width="2.5"/><text x="'+cx+'" y="'+(cy+r-7)+'" text-anchor="middle" font-size="11" fill="#176b60" stroke="white" stroke-width="3" paint-order="stroke">2.5×</text></g>'}
